cat << 'EOF' > src/orchestration/tools/registry.test.ts
import {describe, it, expect, vi} from 'vitest';
import {ToolRegistry} from './registry.js';

describe('ToolRegistry', () => {
  it('rejects input missing a required property and does not call executor', async () => {
    const registry = new ToolRegistry();
    const executor = vi.fn().mockResolvedValue('success');

    registry.register(
      {
        name: 'test_tool',
        description: 'A test tool',
        inputSchema: {
          type: 'object',
          properties: {
            location: { type: 'string' }
          },
          required: ['location']
        }
      },
      executor
    );

    const result = await registry.execute('test_tool', {});

    expect(executor).not.toHaveBeenCalled();
    expect(result.result).toMatch(/location/i);
    expect(result.result).toMatch(/required/i);
  });
});
EOF
